record.content:
Please see here (or in the original, parent entry) the harmonic series \PMlinkname{diagram}{HarmonicSeries} in the page images mode only.

\begin{center}
\begin{pspicture}(-0.5,-0.5)(6,6)
\psaxes[Dx=1,Dy=1]{->}(0,0)(-0.5,-0.5)(5.5,5.5)
\rput(5.5,-0.2){$x$}
\rput(-0.2,5.5){$y$}
\rput(-0.3,-0.3){$0$}
\psplot[linecolor=red]{0.22}{5.2}{1 x div}
\psline(1,0)(1,1)
\psline[linecolor=blue](1,1)(2,1)(2,0.5)(3,0.5)(3,0.333)(4,0.333)(4,0.25)(5,0.25)(5,0.2)
\psline(2,0)(2,0.5)
\psline(3,0)(3,0.333)
\psline(4,0)(4,0.25)
\rput(1,3.5){$y = \frac{1}{x}$}
\end{pspicture}
\end{center}
